                elif val == 6 or val == 4 or val == 8:  # Cross
                    start_c, end_c = (c1, c2) if c1 < c2 else (c2, c1)
                    start_r, end_r = (r1, r2) if r1 < r2 else (r2, r1)
                    for cc in range(start_c, end_c + 1):
                        output[r2][cc] = val
                    for rr in range(start_r, end_r + 1):
